/**
 * Milling tribal-tip seed (CITED, DRAFT-CONFIDENCE).
 *
 * Source-attributed tips drawn from the 24-PDF milling corpus indexed at
 * state/shared/dashboards/milling-pdf-corpus.json. Each tip carries:
 *   - sourceId          → corpus entry ID (e.g. PDF-MILL-HAAS-MILL-OPS-2023)
 *   - sourceTitle       → human-readable source name
 *   - vendor            → Haas/Hurco/Sandvik/Mastercam/SolidCAM/Open Mind/CNCCookbook
 *   - evidenceLevel     → manufacturer_official | manufacturer_training | industry_reference
 *   - confidence        → draft (single-source) | corroborated (≥2 sources)
 *   - corroboratedBy    → other corpus source IDs that confirm
 *   - status            → "draft" until promoted via /pdf-learn re-validation
 *
 * Foxtrot-soul refuse-list compliance:
 *   - Source attribution is mandatory (every tip cites)
 *   - No anonymous tips
 *   - No averaging of conflicting tips (surfaced as separate tips)
 *   - Single-source tips stay draft-status until ≥2-source corroboration
 *
 * This file SEEDS the corpus — full /pdf-learn extraction passes will append
 * page-cited tips with body content. Operators and the mill-studio wizard
 * can already consume the seed via tribal-by-domain milling.
 *
 * PB-MS0/P3 follow-up · slot=foxtrot · 2026-05-26 · session=claude-ef40a9d1
 */

export type MillingTipEvidenceLevel =
  | "manufacturer_official"
  | "manufacturer_training"
  | "manufacturer_sample"
  | "post_processor_doc"
  | "industry_reference";

export type MillingTipConfidence = "draft" | "corroborated" | "doctrine";

export interface CitedMillingTip {
  /** Stable ID — referenced by playbook rules and academy lessons. */
  id: string;
  /** Operation topic this tip applies to (matches milling-pdf-corpus operationTopicIndex keys). */
  operation: string;
  /** One-line headline (operator-readable). */
  headline: string;
  /** Optional longer body (filled in by /pdf-learn extraction passes). */
  body?: string;
  /** Corpus source ID (REQUIRED — no anonymous tips). */
  sourceId: string;
  /** Source human-readable title (REQUIRED). */
  sourceTitle: string;
  /** Vendor (REQUIRED). */
  vendor: string;
  /** Evidence quality. */
  evidenceLevel: MillingTipEvidenceLevel;
  /** Promotion status. */
  confidence: MillingTipConfidence;
  /** Other corpus source IDs that corroborate this tip. */
  corroboratedBy: string[];
  /** Page or section citation (filled in after /pdf-learn). */
  citation?: string;
  /** Material ISO group(s) the tip applies to (P/M/K/N/S/H or "all"). */
  materialScope: string[];
  /** Status — draft pending /pdf-learn re-validation. */
  status: "draft" | "validated";
  /** Tags for tribal-by-domain index. */
  tags: string[];
}

