    operation: "high_feed_milling",
    headline: "Dapra Mini-Feed inserts: chip thinning factor = 4×. Target 0.007\" chip → programmed FPT 0.028\". Compensated FPT range 0.012-0.032\" = actual chip 0.003-0.008\".",
    body: "Mini-Feed inserts have the smallest IC + cross-section. Chip-thinning math: programmed_FPT = target_chip × 4. Light DOC tolerates the upper FPT range (0.032\"); heavier DOC must drop to lower-to-middle (0.012-0.020\"). Index inserts at FIRST visible wear — these break, they don't dull. Trying to push a worn mini-feed insert is how you destroy the holder pocket.",
