    id: "MILL-TIP-DAPRA-MID-FEED-CHIP-THIN-5X",
    operation: "high_feed_milling",
    headline: "Dapra Mid-Feed inserts: chip thinning factor = 5×. Compensated FPT 0.020-0.060\" (T-geom steel/iron) or 0.015-0.050\" (D-geom heat-treated) = actual chip 0.003-0.012\".",
    body: "Mid-Feed cross-section is stronger than Mini-Feed but smaller than Heavy-Feed. T-geometry = positive rake for steels/irons/heat-treated steels (0.020-0.060\" FPT). D-geometry = different rake for stainless/superalloys (0.015-0.050\" FPT). Best fit: 40-taper machines and linear-way mills where heavy-feed inserts would over-load the spindle. Run faster FPT with lighter DOC most situations.",
