    headline: "Haas built-in warm-up: O09220 inside O09000 folder. 4-DAY idle threshold — every Haas spindle idle >4 days MUST be thermally cycled before normal operation, or risk overheat from settled lubrication.",
    body: "Spindle lubrication settles when idle, so the bearings run dry at first start until pumping redistributes oil. Haas's O09220 ramps speed in stages (typically 0→4000→8000→12000 RPM with dwells) over ~10-15 min to redistribute lube + thermally stabilize before production starts. Skip this and you eat through spindle bearings 3-5× faster.",
