    id: "MILL-TIP-HAAS-G25-BALANCED-HOLDER-MANDATORY-10K",
    operation: "machine_setup",
    headline: "Haas warm-up >10,000 RPM spindles: MUST use ANSI S2.19 G2.5-or-better BALANCED tool holder. Unbalanced holder during warm-up = bearing damage from first cycle.",
    body: "G2.5 balance grade limits residual unbalance to <2.5 mm/s peripheral speed at operating RPM. Run-out and unbalance forces grow with RPM² — an empty spindle taper or an unbalanced holder at 12K+ RPM transmits ~4× the radial load of the same imbalance at 6K. Haas docs are explicit: this is NOT just for finishing — the warm-up cycle alone will accelerate bearing wear if the balance is poor. G2.5 verified once per holder; mark with paint stripe + serial.",
