    id: "MILL-TIP-HAAS-COLD-PROBE-HOT-SPINDLE-STUCK",
    operation: "probing",
    headline: "Haas thermal-expansion hazard: cold probe (or any cold holder) loaded into HOT spindle taper → toolholder expands → sticks at next tool change with audible 'pop'. Don't leave probe in hot spindle.",
    body: "Spindle taper holds ~110°F after a long run; a probe pulled from rack at 70°F expands as it equilibrates inside the warm taper — the taper-side metal can't accommodate the OD growth, gripping force exceeds the drawbar's release force. ATC fires retention release, drawbar pops audibly, sometimes drawbar stalls = M19 alarm 'tool not released'. Workaround: at end-of-shift, run M19 to release the probe + park back in tool rack. NEVER leave the cool probe in a hot spindle overnight.",
