    body: "245's positive-rake geometry + 45° entry angle creates two stable regimes: (1) high FPT + heavy DOC for roughing (axial force redirect, low chatter on 40-taper) (2) low FPT + low DOC + wiper insert for mirror finishing on steel/iron. The 'mixed production' use case: same mill, two parameter sets, no tool change. Cast-iron mirror finishes Ra <0.8 µm achievable. NOT the right choice if you need ONLY production economy — that's CoroMill 745.",
