    operation: "ball_end_milling",
    headline: "Mitch Baer: ball-nose 'death spiral' anti-pattern — finish looks bad → operator slows the feed → rubbing gets WORSE → operator slows RPM → tool is now hot, dull, polishing. Then everyone blames the tool. THE SETUP was the problem.",
    body: "The intuitive operator response to a bad finish (slow it down) is exactly wrong for ball-nose surfacing. Slowing feed reduces chip-load → tool can't shear → rubs harder. Slowing RPM kills SFM further → polishing not cutting. Diagnostic recipe: bad ball-nose finish? Ask in order — (1) Am I running enough RPM for the EFFECTIVE diameter? (2) Is step-over small enough for target finish? (3) Am I feeding hard enough to actually cut? Fix THOSE before swapping tools.",
