    operation: "ball_end_milling",
    headline: "Mitch Baer cusp-height step-over guidelines: 3-5% Ø = fine finish, 6-8% = good finish, 10%+ = visible scallops. Cusp height is driven by tool radius + step-over + DOC — NOT by RPM, coding, or magic.",
    body: "Cusp height (the ridge between two adjacent passes on a curved surface) is purely geometric. For a ball-nose: h ≈ (stepover²) / (8 × tool_radius). PT Solutions's operator-direct guidance — 3-5% Ø step-over = mirror-class finish; 6-8% = good visible-fine finish; 10%+ = scallops you can feel and see. Trade-off: smaller step-over = better finish but longer cycle. No way around it. If you're chasing finish, step-over matters more than RPM tweaks.",
