    operation: "plunge_milling",
    headline: "Mitch Baer (PT Solutions): plunge milling produces ~100% AXIAL load. The machine is STRONGEST in the Z axis. Plunge excels in deep pockets, long overhangs, and tough materials where side-mill chatters.",
    body: "Physics nobody tells you: a VMC's spindle column + Z-axis ballscrew is the stiffest force-bearing axis (typically 2-4× stiffer in Z than X/Y). Plunge milling redirects ~all cutting force into Z, exploiting that stiffness. Side-milling at the same MRR loads X+Y → cantilever bending of tool + part → chatter. Plunge milling is a stability strategy first, MRR strategy second. Use when: side-mill chatters no matter what, long tool reach, deep features, stainless/ti/superalloys, untrusted setup.",
