    body: "Pocketing CAM logic assumes the cutter clears material LATERALLY — wrong mental model for plunge milling. Plunge milling clears material via a grid of vertical plunges with discrete step-over between each. Most modern CAM systems (Mastercam, Fusion, hyperMILL, PowerMill) have a DEDICATED plunge roughing strategy — use it. Hand-coding plunge milling with G83 peck-drill cycle + G0 to next XY hole is honest; using 2D pocket motion is dishonest geometry.",
