    operation: "plunge_milling",
    headline: "Mitch Baer: plunge step-over IS your load control. Smaller = lighter load + more plunges (slower but safer). Larger = higher load + faster but stability-marginal. Tune this to balance stability vs speed.",
    body: "Step-over in plunge milling is the primary load-control knob — far more impactful than feed rate. Each plunge cuts a chord of material whose volume = π × (tool_Ø/2)² × plunge_depth × (stepover / tool_Ø). Halve the step-over → halve the per-plunge load. Use ~50-60% Ø for stable production; drop to 30-40% Ø on weak setups or hard materials. Going above 75% loses the stability advantage that justified plunge milling in the first place.",
