    operation: "plunge_milling",
    headline: "Mitch Baer: plunge mills need LOAD, not sympathy. Feed hard enough to keep inserts cutting. Don't creep — rubbing destroys edges. Same anti-pattern as ball-nose: light feed = rubbing = failure.",
    body: "Indexable plunge inserts are designed for axial impact loading — their edge geometry is built to shear under heavy chip-load, NOT to skim. Feeding too light puts the cutting edge in a 'plowing' regime: heat builds up in the carbide instead of leaving in the chip → coating delaminates → edge chips out. Plunge feed-per-tooth typically 0.10-0.25 mm/rev (about 2× a comparable end mill in the same material). When in doubt, feed harder, not softer.",
