    operation: "shoulder_milling",
    headline: "Mitch Baer: shoulder mill is NOT a default roughing tool. Lead-angle face mills + high-feed mills + solid carbide HEM are more efficient. Use shoulder mill only when DOC<1-1.5×D with a relatively wide shoulder, or stepping down a wall too tall for solid carbide.",
    body: "Wrong reason to use a shoulder mill: 'because it has shoulder in the name and I have a shoulder feature'. Right reasons: (1) Following a high-feed roughing pass to finish a floor or wall. (2) Cutting shallow shoulders where DOC<1-1.5×D wastes HEM's full-flute advantage. (3) Stepping down a wall too tall for solid carbide. (4) End-cut performance: shoulder mills end-cut WAY better than solid carbide and prefer >50% step-over. Cost-per-index is also significantly lower than solid carbide. But: don't treat it like a face mill — a lead-angle face mill outperforms for pure facing.",
    sourceId: "PTS-YT-YXO_J2bnFPk",
