    headline: "Mitch Baer: 3 shoulder-mill categories — Single-side (most positive geom, broadest options, RAMPS OK, slots/pockets/profiling); Double-side (neutral axial + positive radial rake, shell-mill ≥2\", NO ramping); Tangentially-mounted (strongest edge, ≥2\", little/no ramping).",
    body: "Choose by need: ramp into pocket = single-side ONLY. Heavy shell milling on ≥2\" body = double-side (stronger geometry, neutral axial rake handles axial impact better). Maximum edge strength at large diameters = tangential mount. Single-side has the broadest insert + corner-radius + reach options, so default to it unless you have a specific reason for double or tangential.",
