    operation: "shoulder_milling",
    headline: "Mitch Baer: shoulder-milling gauge length is CRITICAL — all force is RADIAL against tool side. Every bit of additional gauge length increases vibration, reduces tool life + accuracy. You can turn a perfectly good cutter into a tuning fork. The smaller your spindle, the more critical it is.",
    body: "Shoulder mill cantilever response: deflection scales with L³ (cube of overhang). Going from 50mm to 75mm gauge length isn't 1.5× worse — it's ~3.4× worse. 'Looks sketchy' = it IS sketchy. Worth buying another holder to minimize gauge length. Especially critical on BT30 / smaller spindles where the spindle bearing stiffness is the limiting factor and the holder can amplify vibration far beyond what a CAT50 setup would tolerate.",
