    operation: "face_milling",
    headline: "Mitch Baer: face-mill wiper rule — FEED PER REV must NOT exceed the effective wiper insert width. Exceed it = the wiper can't sweep the full per-rev advance, surface shows ridges. ONE wiper insert per cutter, sized for max IPM.",
    body: "Wiper inserts achieve mirror-class finish at high FPT by sweeping a flat trailing edge across the part. If FPR > wiper width, sections of the surface skip the wiper sweep — visible ridges between revolutions, surface finish degrades. Concrete: wiper width 2 mm → max FPR 2 mm/rev. Inverse: to run faster, install a wider wiper (some cutters take an exchangeable wiper). Wipers come at any insert position but most cutters ONLY accept one — adding a second wiper degrades the geometry.",
