    operation: "face_milling",
    headline: "Mitch Baer face-mill spindle-sizing: BT30 → max 3\" but 2\" runs better. CAT40/HSK63 → max 4\" but 3\" runs best. CAT50/HSK100 → only torque-limited (6\" usually fine). Oversizing past spindle = torque starvation + walking insert.",
    body: "Spindle taper torque capacity scales nonlinearly: BT30 ~30-50 Nm, CAT40 ~80-100 Nm, CAT50 ~250+ Nm. Face-mill power demand scales with cutter Ø² (chip width). Running a 4\" face mill on BT30 = 100% torque usage at light DOC, no headroom for upset = stalls or chips inserts when the cut varies. Run cutter Ø ≤ 2/3 the max your taper supports for production reliability. Cast aluminum at CAT50: PCD on 6\" cutter is the magic combo Mitch calls 'the deal'.",
