    operation: "high_temp_alloy_milling",
    headline: "Mitch Baer ceramic-failure diagnostic key: INSTANT failure = too slow OR coolant used. GRADUAL chipping = too much interruption OR aggressive entry. CRATERING and disappearing = doing it RIGHT, just optimize tool life. No warning before failure — ceramics just quit.",
    body: "Ceramics fail catastrophically with no audible/visible warning (unlike carbide which dulls audibly and visibly). Build the failure-mode → root-cause map BEFORE running: instant fail @ entry = SFM too low or coolant overrode rule 2; gradual edge chipping = path has too many entry/exit events; cratering uniformly = the wear mechanism IS chemical erosion (correct, just predict + plan tool life). For path strategy: trochoidal, peel milling, constant-engagement only. Avoid full slotting + sharp corners + sudden entries.",
