    operation: "high_efficiency_milling",
    headline: "PT Solutions: at 10% radial engagement, you can DOUBLE the SFM (heat is greatly reduced, less goes to tool). Combined chip-thin FPT increase: 4000 IPT × 1.7 × 2.0 SFM = ~170 IPM vs 50 IPM conventional (3.4× faster).",
    body: "Two effects multiply: (a) reduced radial engagement = each tooth cuts less material per revolution = less heat into the tool. (b) Heat reduction lets you raise SFM (which would normally heat-cap). Cap multiplier: at 50% engagement use baseline SFM. At 10% engagement double it. At 5% engagement, conservative shops do 2.5× — but ramp slowly with audio feedback. Combined formula: new_feed_rate = baseline_IPM × CTF × SFM_multiplier. 50 → 170 IPM proves a 3.4× cycle-time improvement is on the table.",
