    operation: "tool_selection",
    headline: "Haas APX end-mill coating split: HEHM + HEPM + HSPM2 use aluminum-CHROMIUM-nitride (AlCrN) — lower friction + higher hot-hardness. HTM2 uses aluminum-TITANIUM-nitride (AlTiN) — slightly harder. Choose by hot-cut conditions vs friction-dominated cuts.",
    body: "AlCrN vs AlTiN selection matters when running production endmills at the limits. AlCrN: lower coefficient of friction (chip slides easier, less heat from friction) + higher hot-hardness ceiling. Best for: high-feed roughing + slotting where chip-load + friction dominate. AlTiN: slightly harder coating overall, more abrasion-resistant. Best for: high-temp alloys (Inconel/Waspaloy) where hot abrasion is the dominant wear mechanism. APX carbide grain: 0.5-0.8 μm (roughing-finishing balance). HSPM2 = highest general-purpose (4-flute + multi-helix + variable pitch); HEPM 6-flute = high-speed trochoidal up to 40 HRC.",
