    operation: "tool_selection",
    headline: "Mitch Baer high-feed mill selection: cutting STEEL/IRON (P/K) → neutral geometry + decent edge prep. Cutting STAINLESS/HIGH-TEMP (M/S) → POSITIVE geometry + SHARPER cutting edge. Wrong geometry-to-material combo = wear acceleration.",
    body: "Steel/iron tolerates a robust insert geometry (slightly negative rake, prepped edge) — the chip forms easily, heat exits readily. Stainless/Inconel/Ti = sticky materials with low thermal conductivity → BUE formation on neutral rake. Positive rake + sharp edge encourages chip flow rather than welding. Wrong combo: positive+sharp insert on steel = edge chips at first chip; neutral+prepped insert on stainless = BUE builds, finish degrades, tool dies. Vendor catalogs map insert geometry codes (e.g. Sandvik 'M' for medium-load, 'L' for sharp/positive) to ISO groups — use these.",
