    headline: "Mitch Baer: on a CAT 40 machine, DON'T spec a high-feed mill larger than 2\" Ø. Better to travel further at high feed rate + optimal parameters than to take a wider cut at compromised feed. Wide cut = high spindle load = compromised stability at CAT 40 torque.",
    body: "High-feed mill cutting force budget scales with cutter Ø² (chip width). CAT 40 torque capacity ~80-100 Nm caps the cutter size that can run optimal FPT × full flute count. Trying a 3\" high-feed at CAT 40 = forced FPT reduction = lose the high-feed productivity advantage entirely. Better: 2\" tool running at full programmed feed → faster cycle time net-net via path coverage. The 'wider cut feels faster' instinct is wrong here — high-feed only works when the cutter is operating in its designed force envelope.",
