    operation: "drilling",
    headline: "Mitch Baer drill-type matrix: (1) HSS/Cobalt — low qty + no coolant + manual; (2) Solid carbide — precision + high volume + through-spindle coolant; (3) Insert-tip solid (>10mm) — replace tip not body, 1mm head increments; (4) Indexable — large Ø only, 1-flute-effective, interrupted-cut friendly.",
    body: "Selection key questions: material? hole Ø & depth? holes-per-part × part qty? through-spindle coolant? HSS-cobalt with parabolic flutes can drill up to 3×D without pecking — good for manual/low-spindle-power setups. Solid carbide regrind path: 3-5 more cycles at fraction of new-tool cost (but track wear, regrind proactively, USE the reground tools — savings only if utilized). Insert-tip solid drill: each body covers a 1mm Ø range, swap tips in seconds, no machine touch-off after swap. Indexable: 1-flute-effective limits FPR but enables huge Ø + interrupted-entry (static-tool in lathe is a sleeper application).",
