    operation: "drilling",
    headline: "Mitch Baer indexable-drill RULE: proper coolant flow is CRITICAL. Coolant starvation = CATASTROPHIC failure (Mitch shows the wreckage). Through-spindle coolant or high-flow side jets — never assume static coolant is enough on an indexable drill.",
    body: "Indexable drills depend on coolant for: (a) chip evacuation up the flute (chips can't exit otherwise — drill seizes), (b) thermal control at the insert edge (carbide cracks under thermal shock if coolant fails mid-cut), (c) lubrication at the high contact pressure between insert and hole wall. Coolant pressure floor ~300 psi for standard indexable; deep-hole + difficult materials need 1000+ psi through-spindle. NEVER run an indexable drill with marginal coolant — it doesn't just dull, it explodes.",
