    operation: "tool_management",
    headline: "Mitch Baer solid-carbide regrind doctrine: regrind PROACTIVELY — not when the tool is too damaged. Track tool life, regrind at the 80% mark. Get 3-5 MORE life cycles at a fraction of new-tool cost. 'It's not a savings if nobody uses them.'",
    body: "Reground solid carbide drills/end mills run at near-new performance IF the regrind happens before catastrophic edge breakdown. Past 80% wear: chipping propagates into the substrate → regrind has to remove too much material → diameter loses spec → reground tool is unusable for tight-tol holes. Track via shop-floor tool-life log (or tool-management service). Critical companion practice: USE the reground tools (label them, sequence them in the tool changer, don't leave them shelf-bound) — savings only realize when they cut metal.",
