    id: "MILL-TIP-SANDVIK-TITANIUM-HEM-LONG-ENGAGEMENT",
    operation: "high_efficiency_milling",
    headline: "Sandvik Ben (titanium HEM, w/ Fusion 360): Long axial engagement + small radial stepover + high Vc BEATS the old 'almost 100% step-over + tiny stepdown' approach. Heat management = grade + low thermal conductivity insert + path strategy ALL combined.",
    body: "Titanium heat management is the limiting factor — Ti has thermal conductivity ~7 W/m·K (1/10 of steel). All cutting heat that doesn't leave with the chip goes into the tool. HEM strategy: large AP (axial depth, e.g. full 3×D flute length) + small AE (radial step-over, ~10%) + high Vc (surface speed) lets the tool run cool because (a) chip is thick + carries heat out, (b) each tooth contact is brief + spread across the full flute length, (c) high Vc means chip leaves before heat soaks. Sandvik Plura 5×D solid carbide end mills are designed for this exact pattern.",
