    operation: "drilling",
    headline: "Mitch Baer quotes a wise man: 'CENTER DRILLS DO NOT CENTER DRILLS.' Using a center drill to spot for a carbide drill DAMAGES it — initial contact is at the fragile carbide corners → chipping → notching → crooked holes.",
    body: "Center/combined drills have a smaller pilot diameter than a carbide drill's outer edge — when the carbide drill enters the pilot, the fragile carbide corners hit material first instead of the strong drill tip. Result: corner chipping during entry, propagating into oversize hole, poor finish, axial drift. Center drills are for centers ON A LATHE (live/dead center support pockets) — that's why they have 60/82/90° included angle + body + pilot. They were never designed to spot for CNC drilling.",
