    operation: "drilling",
    headline: "Mitch Baer carbide drill spotting rule: spot drill angle MUST BE GREATER than the carbide drill's point angle. OR — don't spot at all if drill is self-centering and ≤5×D. A smaller-angle spot drill positions the carbide drill on its corners → corners chip first.",
    body: "Know your carbide drill's point angle (typically 118°, 130°, 135°, 140°, 142°, or 150°). Spot with an angle EQUAL OR LARGER — that way the carbide drill's main tip hits material first, transferring force through the strongest part of the drill. Or skip spotting entirely: modern self-centering carbide drills (point geometry like S-point or 4-facet) handle their own centering up to 5×D, no spot required. 90° spot drill leaves a chamfer for free but the trade-off is risk to the carbide drill — better practice: drill first, chamfer AFTER with a dedicated chamfer mill.",
