    headline: "Mitch Baer: drills don't just cut UNDERSIZE — they SPIRAL, throwing off precision in ways calipers can't catch. Use on-size gauge pins or small-hole gauges to verify. Drilling success cascades into tapping/reaming/boring success — get it right first.",
