/**
 * Lookup tips for a given milling operation. Used by KnowledgeCurriculumBridgeEngine
 * to surface cited tribal knowledge during /mill-studio runs.
 *
 * @param operation Operation topic (face_milling, pocket_milling, slotting, …)
 * @returns Array of cited tips for that operation, severity-ordered by evidence level
 */
export function tipsForMillingOperation(operation: string): CitedMillingTip[] {
  const EVIDENCE_RANK: Record<MillingTipEvidenceLevel, number> = {
    manufacturer_official: 4,
    manufacturer_training: 3,
    post_processor_doc: 2,
    industry_reference: 1,
    manufacturer_sample: 0,
  };
  return MILLING_PDF_CITED_TIPS
    .filter(t => t.operation === operation)
    .sort((a, b) => EVIDENCE_RANK[b.evidenceLevel] - EVIDENCE_RANK[a.evidenceLevel]);
}

/**
 * Get all distinct operations covered by the cited tribal-tip seed.
 */
export function listMillingOperationsWithTips(): string[] {
  return [...new Set(MILLING_PDF_CITED_TIPS.map(t => t.operation))].sort();
}
